@section('content')
<header class="shop-hero"><div><p class="eyebrow">Inchangs Boutique Online</p><h1>Curated outfits for everyday confidence.</h1><p>Browse dresses, tops, sets, and accessories managed by the boutique admin.</p></div><div class="cart-box"><h2>Cart</h2><div id="cartItems" class="cart-items muted">Your cart is empty.</div><strong id="cartTotal">PHP 0.00</strong>@if(session('user'))<form id="checkoutForm" class="form-grid compact"><label>Shipping Address<input type="text" name="shipping_address" required></label><label>Payment<select name="payment_method" required><option value="cash_on_delivery">Cash on Delivery</option><option value="gcash">GCash</option><option value="card">Card</option></select></label><button class="btn primary" type="submit">Checkout</button></form>@else<a class="btn primary" href="{{ route('login') }}">Login to Checkout</a>@endif</div></header><section class="toolbar"><input id="searchBox" type="search" placeholder="Search boutique items"><select id="categoryFilter"><option value="">All categories</option></select></section><section id="productGrid" class="product-grid"></section>
