@push('scripts')<script>let products=[],cart={};function money(n){return'PHP '+Number(n).toFixed(2)}function loadShop(){$.getJSON('/api/shop-products',{search:$('#searchBox').val(),category_id:$('#categoryFilter').val()},function(res){products=res.data;if($('#categoryFilter option').length===1)res.categories.forEach(c=>$('#categoryFilter').append(`<option value="${c.id}">${c.name}</option>`));$('#productGrid').html(products.map(p=>`<article class="product-card"><img src="${p.image_url||'/images/products/default.svg'}" alt="${p.name}"><div><span>${p.category}</span><h2>${p.name}</h2><p>${p.description||''}</p><strong>${money(p.price)}</strong><small>${p.size||'Free size'} Â· ${p.color||'Assorted'} Â· ${p.stock} left</small><button class="btn primary" onclick="addToCart(${p.id})">Add to Cart</button></div></article>`).join(''));});}function addToCart(id){cart[id]=(cart[id]||0)+1;renderCart();}function renderCart(){const lines=Object.keys(cart).map(id=>({product:products.find(p=>p.id==id),qty:cart[id]})).filter(x=>x.product);if(!lines.length){$('#cartItems').html('Your cart is empty.');$('#cartTotal').text(money(0));return;}let total=0;$('#cartItems').html(lines.map(x=>{total+=x.product.price*x.qty;return`<div><span>${x.product.name} x ${x.qty}</span><button onclick="cart[${x.product.id}]--; if(cart[${x.product.id}]<=0) delete cart[${x.product.id}]; renderCart();">-</button></div>`}).join(''));$('#cartTotal').text(money(total));}$('#searchBox,#categoryFilter').on('input change',loadShop);$('#checkoutForm').on('submit',function(e){e.preventDefault();const items=Object.keys(cart).map(id=>({product_id:id,quantity:cart[id]}));ajaxJson('/checkout','POST',{shipping_address:$('[name=shipping_address]').val(),payment_method:$('[name=payment_method]').val(),items},function(){cart={};renderCart();loadShop();});});loadShop();</script>@endpush
